package com.example.demo.web;
import com.example.demo.model.Reporte; import com.example.demo.repository.ReporteRepository;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/reportes")
public class ReporteController{
 private final ReporteRepository repo; public ReporteController(ReporteRepository r){repo=r;}
 @GetMapping public List<Reporte> listar(){ return repo.findAll(); }
 @GetMapping("/seguimiento/{codigo}") public Reporte seguimiento(@PathVariable String codigo){return repo.findByCodigo(codigo).orElseThrow();}
 @PostMapping public ResponseEntity<Reporte> crear(@Valid @RequestBody ReporteRequest r,Authentication a){if(!esAdmin(a)&&!esUsuario(a))throw new AccessDeniedException("Solo usuarios y administradores pueden crear reportes");var x=new Reporte(); x.setCodigo("RW-"+System.currentTimeMillis()%1000000); x.setTitulo(r.titulo());x.setDescripcion(r.descripcion());x.setCategoria(r.categoria());x.setUbicacion(r.ubicacion());x.setUrgencia(r.urgencia());x.setFotoUrl(r.fotoUrl());x.setEstado("RECIBIDO");x.setCreadoPor(a.getName());x.setCreadoEn(LocalDateTime.now());x.setActualizadoEn(LocalDateTime.now());return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(x));}
 @PatchMapping("/{id}") public Reporte actualizar(@PathVariable Long id,@Valid @RequestBody ReporteUpdateRequest r,Authentication a){if(!esAdmin(a)&&!esTecnico(a)) throw new AccessDeniedException("Solo personal autorizado");var x=repo.findById(id).orElseThrow();x.setEstado(r.estado());x.setResponsable(r.responsable());x.setSolucion(r.solucion());x.setMateriales(r.materiales());x.setProgramadoPara(r.programadoPara());x.setActualizadoEn(LocalDateTime.now());return repo.save(x);}
 @DeleteMapping("/{id}") public Reporte marcarRealizado(@PathVariable Long id,Authentication a){if(!esAdmin(a)&&!esTecnico(a))throw new AccessDeniedException("Solo técnicos y administradores pueden marcar reportes como realizados");var x=repo.findById(id).orElseThrow();x.setEstado("RESUELTO");if(x.getSolucion()==null||x.getSolucion().isBlank())x.setSolucion("Reporte marcado como realizado");x.setActualizadoEn(LocalDateTime.now());return repo.save(x);}
 @GetMapping("/indicadores") public Map<String,Object> indicadores(){var all=repo.findAll();var m=new LinkedHashMap<String,Object>();m.put("total",all.size());m.put("recibidos",all.stream().filter(x->x.getEstado().equals("RECIBIDO")).count());m.put("enProceso",all.stream().filter(x->x.getEstado().equals("EN_PROCESO")).count());m.put("resueltos",all.stream().filter(x->x.getEstado().equals("RESUELTO")).count());m.put("urgentes",all.stream().filter(x->x.getUrgencia().equals("ALTA")).count());return m;}
 private boolean esAdmin(Authentication a){return tieneRol(a,"ROLE_ADMINISTRADOR");} private boolean esTecnico(Authentication a){return tieneRol(a,"ROLE_TECNICO");} private boolean esUsuario(Authentication a){return tieneRol(a,"ROLE_USUARIO");} private boolean tieneRol(Authentication a,String rol){return a!=null&&a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals(rol));}
}
